"""
HTML/JS Template for TradingView Lightweight Charts
"""

TV_HTML_TEMPLATE = """<!DOCTYPE html><html><head><meta charset="utf-8"/><script src="https://unpkg.com/lightweight-charts@4.1.3/dist/lightweight-charts.standalone.production.js"></script><style>*{margin:0;padding:0;box-sizing:border-box;}body{background:#131722;color:#D1D4DC;font-family:-apple-system,sans-serif;overflow:hidden;}#wrap{position:relative;width:100%;height:__HEIGHT__px;}#chart{width:100%;height:100%;}#legend{position:absolute;top:8px;left:10px;z-index:10;font-size:12px;font-weight:500;background:rgba(19,23,34,0.9);padding:5px 9px;border-radius:4px;border:1px solid rgba(42,46,57,0.7);pointer-events:none;line-height:1.5;}.t-title{font-weight:700;color:#FFF;font-size:13px;}.t-bar{position:absolute;bottom:6px;left:10px;z-index:10;display:flex;gap:4px;}.t-btn{background:#1E222D;color:#787B86;border:1px solid #2A2E39;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;cursor:pointer;}.t-btn:hover,.t-btn.act{background:#2962FF;color:#FFF;border-color:#2962FF;}</style></head><body><div id="wrap"><div id="legend"><div class="t-title">__SYMBOL__ • Daily</div><div id="l1"></div><div id="l2"></div><div id="l3"></div></div><div id="chart"></div><div class="t-bar"><button class="t-btn" onclick="sTf(30,event)">1M</button><button class="t-btn" onclick="sTf(90,event)">3M</button><button class="t-btn" onclick="sTf(180,event)">6M</button><button class="t-btn act" onclick="sTf(250,event)">1Y</button><button class="t-btn" onclick="sTf(750,event)">3Y</button><button class="t-btn" onclick="fAll(event)">ALL</button></div></div><script>const ct=document.getElementById('chart'),l1=document.getElementById('l1'),l2=document.getElementById('l2'),l3=document.getElementById('l3');const chart=LightweightCharts.createChart(ct,{width:ct.clientWidth,height:ct.clientHeight,layout:{background:{color:'#131722'},textColor:'#9CA3AF'},grid:{vertLines:{color:'rgba(42,46,57,0.5)'}},crosshair:{mode:LightweightCharts.CrosshairMode.Normal},rightPriceScale:{borderColor:'rgba(42,46,57,0.8)',scaleMargins:{top:0.04,bottom:0.30}},timeScale:{borderColor:'rgba(42,46,57,0.8)',timeVisible:true}});const cs=chart.addCandlestickSeries({upColor:'#089981',downColor:'#F23645',borderVisible:false,wickUpColor:'#089981',wickDownColor:'#F23645'});const cd=__CANDLES_JSON__;cs.setData(cd);const vs=chart.addHistogramSeries({priceFormat:{type:'volume'},priceScaleId:'vol',scaleMargins:{top:0.78,bottom:0}});vs.setData(__VOLUME_JSON__);chart.priceScale('vol').applyOptions({scaleMargins:{top:0.78,bottom:0}});let bbu,bbm,bbl,m20,m50,m200;if(__SHOW_BB__){bbu=chart.addLineSeries({color:'#29B6F6',lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false});bbu.setData(__BBU_JSON__);bbm=chart.addLineSeries({color:'#FF5252',lineWidth:1,priceLineVisible:false,lastValueVisible:false});bbm.setData(__BBM_JSON__);bbl=chart.addLineSeries({color:'#29B6F6',lineWidth:1,lineStyle:2,priceLineVisible:false,lastValueVisible:false});bbl.setData(__BBL_JSON__);}if(__SHOW_M20__){m20=chart.addLineSeries({color:'#AB47BC',lineWidth:1,priceLineVisible:false,lastValueVisible:false});m20.setData(__M20_JSON__);}if(__SHOW_M50__){m50=chart.addLineSeries({color:'#29B6F6',lineWidth:2,priceLineVisible:false,lastValueVisible:false});m50.setData(__M50_JSON__);}if(__SHOW_M200__){m200=chart.addLineSeries({color:'#FFA726',lineWidth:2,priceLineVisible:false,lastValueVisible:false});m200.setData(__M200_JSON__);}function fmtP(v){if(!v||isNaN(v))return'-';if(v>=1000)return v.toLocaleString(undefined,{maximumFractionDigits:0});return v.toFixed(2);}function fmtV(v){if(!v)return'0';if(v>=1e6)return(v/1e6).toFixed(2)+'M';if(v>=1e3)return(v/1e3).toFixed(1)+'K';return v.toLocaleString();}function uLg(p){let d=(p&&p.time)?p.seriesData.get(cs):(cd.length?cd[cd.length-1]:null);if(d){const diff=d.close-d.open,col=diff>=0?'#089981':'#F23645';const vItem=p?p.seriesData.get(vs):null;const vVal=vItem?vItem.value:(vd.length?vd[vd.length-1].value:0);l1.innerHTML=`<span>O <b style="color:${col}">${fmtP(d.open)}</b></span><span style="margin-left:8px;">H <b style="color:${col}">${fmtP(d.high)}</b></span><span style="margin-left:8px;">L <b style="color:${col}">${fmtP(d.low)}</b></span><span style="margin-left:8px;">C <b style="color:${col}">${fmtP(d.close)}</b></span><span style="margin-left:10px;">Vol <b style="color:${col}">${fmtV(vVal)}</b></span>`;let l2H='';if(m20&&p&&p.seriesData.get(m20))l2H+=`<span>MA20 <b style="color:#AB47BC;margin-left:3px;">${fmtP(p.seriesData.get(m20).value)}</b></span>`;if(m50&&p&&p.seriesData.get(m50))l2H+=`<span style="margin-left:10px;">MA50 <b style="color:#29B6F6;margin-left:3px;">${fmtP(p.seriesData.get(m50).value)}</b></span>`;if(m200&&p&&p.seriesData.get(m200))l2H+=`<span style="margin-left:10px;">MA200 <b style="color:#FFA726;margin-left:3px;">${fmtP(p.seriesData.get(m200).value)}</b></span>`;l2.innerHTML=l2H;let l3H='';if(bbu&&bbm&&bbl&&p&&p.seriesData.get(bbm)){const mv=p.seriesData.get(bbm).value,uv=p.seriesData.get(bbu)?p.seriesData.get(bbu).value:mv,lv=p.seriesData.get(bbl)?p.seriesData.get(bbl).value:mv;l3H=`<span>BB 20 2</span><b style="color:#FF5252;margin-left:6px;">${fmtP(mv)}</b><b style="color:#29B6F6;margin-left:8px;">${fmtP(uv)}</b><b style="color:#29B6F6;margin-left:8px;">${fmtP(lv)}</b>`;}l3.innerHTML=l3H;}}chart.subscribeCrosshairMove(uLg);uLg(null);function sTf(n,e){if(!cd.length)return;const s=Math.max(0,cd.length-n);chart.timeScale().setVisibleRange({from:cd[s].time,to:cd[cd.length-1].time});document.querySelectorAll('.t-btn').forEach(b=>b.classList.remove('act'));if(e&&e.target)e.target.classList.add('act');}function fAll(e){chart.timeScale().fitContent();document.querySelectorAll('.t-btn').forEach(b=>b.classList.remove('act'));if(e&&e.target)e.target.classList.add('act');}sTf(250);window.addEventListener('resize',()=>chart.resize(ct.clientWidth,ct.clientHeight));</script></body></html>"""
